(()=>{'use strict';const $=id=>document.getElementById(id);$('claim').onclick=async()=>{try{const r=await JK_CLOUD.claimSupportDiagnostic({baseUrl:$('baseUrl').value,code:$('code').value,supportClientId:$('clientId').value});const b=r.bundle;if(!b?.privacy||b.privacy.containsPin||b.privacy.containsSessionToken||b.privacy.containsRawHandwriting)throw new Error('개인정보 계약 검증 실패');const blob=new Blob([JSON.stringify(b,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`JK_ENG_Support_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);$('result').textContent=`성공\n지원 ID: ${r.supportId}\n코드 사용 완료: ${r.oneTimeCodeConsumed}\n세션 발급: ${r.sessionGranted}\n진단 상태: ${b.observability?.status||'unknown'}`}catch(e){$('result').textContent=`실패: ${e.message||e}`}}})();
